update public.organization_settings set
  tagline_hi = 'विश्वास, ईमानदारी, पारदर्शिता एवं सभी के लिए समान न्याय',
  tagline = 'Trust, honesty, transparency and equal justice for all',
  about_short_hi = 'प्रगतिशील जायसवाल (कन्नौजिया) कलार समाज, छत्तीसगढ़ — बिलासपुर, जांजगीर-चाम्पा, कोरबा और रायपुर अंचल का पंजीकृत सामाजिक संगठन; 20 सामाजिक क्षेत्र, निर्वाचित कार्यकारिणी, अपना संविधान।',
  about_short = 'Registered social organization of the Kalar community of Bilaspur, Janjgir-Champa, Korba and Raipur (Chhattisgarh): 20 social regions, an elected executive and its own constitution.',
  about_long_hi = '## हमारा परिचय
प्रगतिशील जायसवाल (कन्नौजिया) कलार समाज, छत्तीसगढ़ — बिलासपुर, जांजगीर-चाम्पा, कोरबा और रायपुर अंचल में बसे कलार समाज का पंजीकृत सामाजिक संगठन। समाज अपने संविधान, 20 सामाजिक क्षेत्रों और निर्वाचित कार्यकारिणी के माध्यम से चलता है। यह वेबसाइट समाज की गतिविधियाँ, सदस्यता व परिवार (वंश वृक्ष) की जानकारी, शोक संदेश और विवाह-योग्य युवाओं की सूचना एक जगह लाने का प्रयास है।

## दृष्टि (Vision)
कलार समाज के प्रत्येक सदस्य का आर्थिक, सामाजिक, शैक्षणिक, राजनीतिक और पारिवारिक — हर स्तर पर समग्र विकास।

## लक्ष्य (Mission)
समाज के सभी सदस्यों को एक सूत्र में जोड़कर ऐसा सशक्त, संगठित और प्रभावी समाज बनाना जो एकता बनाए रखते हुए आर्थिक, सामाजिक, शैक्षणिक और राजनीतिक रूप से आगे बढ़े।

## मूल्य (Values)
**विश्वास, ईमानदारी, पारदर्शिता एवं सभी के लिए समान न्याय व्यवस्था।**

## उद्देश्य
- समाज की परंपरा, संस्कृति और इतिहास का संरक्षण व संवर्धन; रूढ़िवादिता, निरक्षरता और अंधविश्वास में कमी
- शोषण-मुक्त, प्रगतिशील समाज की स्थापना
- सदस्यता पंजीयन और नियमित सामाजिक सम्मेलन, जिससे एकता बढ़े
- शिक्षा के कार्यक्रम, प्रतिभाओं का सम्मान; युवाओं के लिए रोज़गार व व्यवसाय की जानकारी
- महिला सशक्तिकरण, नशामुक्त परिवार, स्वास्थ्य शिविर
- विवाह-योग्य युवाओं की जानकारी और सामूहिक आदर्श विवाह
- पत्रिका व वेबसाइट; भूमि-भवन, विद्यालय, छात्रावास, वृद्धाश्रम और धर्मशाला की दिशा में प्रयास
- वृक्षारोपण और स्वच्छता अभियान

## संविधान
समाज का संविधान और उसकी अनुसूचियाँ (सदस्यता नियम, क्षेत्र विभाजन, कार्यकारिणी नियमावली, विवाद निराकरण, सामाजिक संस्कार) इसी वेबसाइट पर [संविधान](/p/samvidhan) पेज पर उपलब्ध हैं।',
  about_long = coalesce(about_long, '## हमारा परिचय
प्रगतिशील जायसवाल (कन्नौजिया) कलार समाज, छत्तीसगढ़ — बिलासपुर, जांजगीर-चाम्पा, कोरबा और रायपुर अंचल में बसे कलार समाज का पंजीकृत सामाजिक संगठन। समाज अपने संविधान, 20 सामाजिक क्षेत्रों और निर्वाचित कार्यकारिणी के माध्यम से चलता है। यह वेबसाइट समाज की गतिविधियाँ, सदस्यता व परिवार (वंश वृक्ष) की जानकारी, शोक संदेश और विवाह-योग्य युवाओं की सूचना एक जगह लाने का प्रयास है।

## दृष्टि (Vision)
