insert into public.cms_pages(organization_id, slug, title, title_hi, blocks, status, show_in_menu, menu_order, seo)
values ((select id from core.organizations where slug = 'pragatishil-kalar-samaj'), 'sadasyata-niyam', 'सदस्यता सम्बन्धी नियम', 'सदस्यता सम्बन्धी नियम', '[{"id": "t1", "type": "text", "heading": "अनुसूची 1 — सदस्यता सम्बन्धी नियम", "heading_hi": "अनुसूची 1 — सदस्यता सम्बन्धी नियम", "body": "## सदस्यता के प्रकार\n- **सामान्य वार्षिक सदस्यता**\n- **विशिष्ट वार्षिक सदस्यता**\n- **संरक्षक सदस्यता** — आजीवन; संरक्षक सदस्य कार्यकारिणी के आजीवन सदस्य होते हैं\n- **पूर्व अध्यक्षगण** — कार्यकारिणी के आजीवन सदस्य\n\n## शुल्क\n- आवेदन शुल्क: ₹5\n- सामान्य वार्षिक सदस्यता: न्यूनतम ₹20 प्रति वर्ष\n- विशिष्ट वार्षिक सदस्यता: ₹1000 प्रति वर्ष\n- संरक्षक सदस्यता: ₹5001 (चाम्पा महासभा में संशोधित)\n- पुनः सदस्यता: बकाया राशि के साथ ₹5 अतिरिक्त\n\n## पात्रता और प्रक्रिया\n- समाज के प्रत्येक वयस्क (18 वर्ष या अधिक) व्यक्ति के लिए सदस्यता लेना अनिवार्य है।\n- इच्छुक व्यक्ति निर्धारित प्रपत्र में आवेदन संगठन के अध्यक्ष या सचिव को देगा; आवेदन शुल्क साथ में जमा होगा।\n- इस वेबसाइट पर [सदस्य बनें](/join) से ऑनलाइन आवेदन किया जा सकता है; मंज़ूरी क्षेत्रीय/संगठन के एडमिन देते हैं।\n\n## कर्तव्य\n- हर वर्ष वार्षिक सदस्यता शुल्क देना।\n- कार्यकारिणी के प्रत्येक सदस्य के लिए विशिष्ट वार्षिक सदस्यता (₹1000) अनिवार्य है।\n\n## सदस्यता की समाप्ति\n- वार्षिक शुल्क तीन माह से अधिक समय तक न देने पर सदस्यता समाप्त की जा सकती है।\n- नैतिक पतन से जुड़े आपराधिक दुराचरण को सदस्यता से वंचित करने का पर्याप्त कारण माना गया है।\n- सदस्यता से जुड़े विवादों का निराकरण कार्यकारिणी समिति करेगी।", "body_hi": "## सदस्यता के प्रकार\n- **सामान्य वार्षिक सदस्यता**\n- **विशिष्ट वार्षिक सदस्यता**\n- **संरक्षक सदस्यता** — आजीवन; संरक्षक सदस्य कार्यकारिणी के आजीवन सदस्य होते हैं\n- **पूर्व अध्यक्षगण** — कार्यकारिणी के आजीवन सदस्य\n\n## शुल्क\n- आवेदन शुल्क: ₹5\n- सामान्य वार्षिक सदस्यता: न्यूनतम ₹20 प्रति वर्ष\n- विशिष्ट वार्षिक सदस्यता: ₹1000 प्रति वर्ष\n- संरक्षक सदस्यता: ₹5001 (चाम्पा महासभा में संशोधित)\n- पुनः सदस्यता: बकाया राशि के साथ ₹5 अतिरिक्त\n\n## पात्रता और प्रक्रिया\n- समाज के प्रत्येक वयस्क (18 वर्ष या अधिक) व्यक्ति के लिए सदस्यता लेना अनिवार्य है।\n- इच्छुक व्यक्ति निर्धारित प्रपत्र में आवेदन संगठन के अध्यक्ष या सचिव को देगा; आवेदन शुल्क साथ में जमा होगा।\n- इस वेबसाइट पर [सदस्य बनें](/join) से ऑनलाइन आवेदन किया जा सकता है; मंज़ूरी क्षेत्रीय/संगठन के एडमिन देते हैं।\n\n## कर्तव्य\n- हर वर्ष वार्षिक सदस्यता शुल्क देना।\n- कार्यकारिणी के प्रत्येक सदस्य के लिए विशिष्ट वार्षिक सदस्यता (₹1000) अनिवार्य है।\n\n## सदस्यता की समाप्ति\n- वार्षिक शुल्क तीन माह से अधिक समय तक न देने पर सदस्यता समाप्त की जा सकती है।\n- नैतिक पतन से जुड़े आपराधिक दुराचरण को सदस्यता से वंचित करने का पर्याप्त कारण माना गया है।\n- सदस्यता से जुड़े विवादों का निराकरण कार्यकारिणी समिति करेगी।", "width": "narrow"}]'::jsonb, 'published', false, 2, '{}'::jsonb)
