insert into public.cms_pages(organization_id, slug, title, title_hi, blocks, status, show_in_menu, menu_order, seo)
values ((select id from core.organizations where slug = 'pragatishil-kalar-samaj'), 'kshetra-vibhajan', 'क्षेत्र विभाजन एवं आश्रित ग्राम', 'क्षेत्र विभाजन एवं आश्रित ग्राम', '[{"id": "t1", "type": "text", "heading": "अनुसूची 2 — क्षेत्र विभाजन एवं आश्रित ग्राम", "heading_hi": "अनुसूची 2 — क्षेत्र विभाजन एवं आश्रित ग्राम", "body": "समाज का कार्यक्षेत्र 20 सामाजिक क्षेत्रों में बँटा है; हर क्षेत्र से एक **क्षेत्रीय सचिव** निर्वाचित होता है। हर परिवार का *मूल ग्राम* इन्हीं क्षेत्रों से जुड़ता है (वंश वृक्ष में \"मूल ग्राम\" इसी सूची से चुना जाता है)।\n\n1. **बिलासपुर** — बिलासपुर, मुंगेली\n2. **सीपत** — सीपत, मटियारी, नरगोड़ा, गुड़ी, धनिया, बिटकुला\n3. **अकलतरा** — अकलतरा, पोड़ी, कोटमी, किरारी, फरहदा, कुकदा\n4. **तेंदूभांठा** — तेंदूभांठा, हरदी\n5. **कुरदा** — कुरदा, जांजगीर, चाम्पा, सोंठी, पिसौद, जगदल्ला\n6. **फरसवानी** — फरसवानी, सिवनी, महुदा, गीतारी, केराकछार\n7. **सकरेली** — सकरेली, बाराद्वार, असौंदा, हाटकुरदा, जर्वे, जाजंग, नगरदा\n8. **गांडापाली** — गांडापाली, ढोढा तराई, चिकनीपाली\n9. **बरपाली** — बरपाली, सलिहाभांठा, संडैल\n10. **भैसमा** — भैसमा, तिलकेजा, जुनवानी, करतला\n11. **तरदा** — तरदा, उरगा\n12. **पंतोरा** — पंतोरा, पहरिया, पुरेना, बुड़गहन, सत्तीगुड़ी\n13. **भिलाईबाजार** — भिलाईबाजार, हरदीबाजार, गेवरा, कुसमुंडा, विकास नगर\n14. **दीपका** — दीपका, मनगांव, लक्ष्मणनगर, पाली\n15. **नवागांव** — नवागांव, कटघोरा, चैतमा, मोरगा\n16. **छुरी** — छुरी, बांकीमोंगरा\n17. **कोरबा** — कोरबा शहर, निहारिका टाकीज परिक्षेत्र, छ.ग.रा.वि.मं. पूर्व\n18. **बालको** — बालको नगर, रजगामार\n19. **एन. टी. पी. सी.** — एन.टी.पी.सी., दर्री, जमनीपाली, छ.ग.वि.मं. पश्चिम कालोनी, बलगी\n20. **रायपुर** — रायपुर, भिलाई, दुर्ग, गरियाबंद", "body_hi": "समाज का कार्यक्षेत्र 20 सामाजिक क्षेत्रों में बँटा है; हर क्षेत्र से एक **क्षेत्रीय सचिव** निर्वाचित होता है। हर परिवार का *मूल ग्राम* इन्हीं क्षेत्रों से जुड़ता है (वंश वृक्ष में \"मूल ग्राम\" इसी सूची से चुना जाता है)।\n\n1. **बिलासपुर** — बिलासपुर, मुंगेली\n2. **सीपत** — सीपत, मटियारी, नरगोड़ा, गुड़ी, धनिया, बिटकुला\n3. **अकलतरा** — अकलतरा, पोड़ी, कोटमी, किरारी, फरहदा, कुकदा\n4. **तेंदूभांठा** — तेंदूभांठा, हरदी\n5. **कुरदा** — कुरदा, जांजगीर, चाम्पा, सोंठी, पिसौद, जगदल्ला\n6. **फरसवानी** — फरसवानी, सिवनी, महुदा, गीतारी, केराकछार\n7. **सकरेली** — सकरेली, बाराद्वार, असौंदा, हाटकुरदा, जर्वे, जाजंग, नगरदा\n8. **गांडापाली** — गांडापाली, ढोढा तराई, चिकनीपाली\n9. **बरपाली** — बरपाली, सलिहाभांठा, संडैल\n10. **भैसमा** — भैसमा, तिलकेजा, जुनवानी, करतला\n11. **तरदा** — तरदा, उरगा\n12. **पंतोरा** — पंतोरा, पहरिया, पुरेना, बुड़गहन, सत्तीगुड़ी\n13. **भिलाईबाजार** — भिलाईबाजार, हरदीबाजार, गेवरा, कुसमुंडा, विकास नगर\n14. **दीपका** — दीपका, मनगांव, लक्ष्मणनगर, पाली\n15. **नवागांव** — नवागांव, कटघोरा, चैतमा, मोरगा\n16. **छुरी** — छुरी, बांकीमोंगरा\n17. **कोरबा** — कोरबा शहर, निहारिका टाकीज परिक्षेत्र, छ.ग.रा.वि.मं. पूर्व\n18. **बालको** — बालको नगर, रजगामार\n19. **एन. टी. पी. सी.** — एन.टी.पी.सी., दर्री, जमनीपाली, छ.ग.वि.मं. पश्चिम कालोनी, बलगी\n20. **रायपुर** — रायपुर, भिलाई, दुर्ग, गरियाबंद", "width": "wide"}]'::jsonb, 'published', false, 3, '{}'::jsonb)
