insert into public.cms_pages(organization_id, slug, title, title_hi, blocks, status, show_in_menu, menu_order, seo)
values ((select id from core.organizations where slug = 'pragatishil-kalar-samaj'), 'karyakarini-niyamavali', 'कार्यकारिणी एवं नियमावली', 'कार्यकारिणी एवं नियमावली', '[{"id": "t1", "type": "text", "heading": "अनुसूची 3 — कार्यकारिणी एवं नियमावली (धारा 16)", "heading_hi": "अनुसूची 3 — कार्यकारिणी एवं नियमावली (धारा 16)", "body": "## नियम 1 — क्षेत्र और क्षेत्रीय सचिव\nसमाज के गाँव सामाजिक क्षेत्रों (इकाइयों) में बँटे हैं ([सूची](/p/kshetra-vibhajan)); हर क्षेत्र के सदस्य अपना **क्षेत्रीय सचिव** चुनते हैं।\n\n## नियम 2 — पदाधिकारियों का निर्वाचन\nअध्यक्ष, उपाध्यक्ष, सचिव, सहसचिव और कोषाध्यक्ष का चुनाव गुप्त मतदान से होता है। महिला प्रकोष्ठ, युवा प्रकोष्ठ और अन्य प्रकोष्ठों के प्रभारी नामांकित किए जाते हैं।\n\n## नियम 3 — कार्यकारिणी समिति\nकार्यकारिणी में निर्वाचित पदाधिकारी, सभी क्षेत्रीय सचिव, प्रकोष्ठ प्रभारी, संरक्षक सदस्य (आजीवन) और पूर्व अध्यक्षगण (आजीवन) शामिल होते हैं।\n\nवर्तमान पदाधिकारियों की सूची [हमारे बारे में](/about) पेज पर देखें।", "body_hi": "## नियम 1 — क्षेत्र और क्षेत्रीय सचिव\nसमाज के गाँव सामाजिक क्षेत्रों (इकाइयों) में बँटे हैं ([सूची](/p/kshetra-vibhajan)); हर क्षेत्र के सदस्य अपना **क्षेत्रीय सचिव** चुनते हैं।\n\n## नियम 2 — पदाधिकारियों का निर्वाचन\nअध्यक्ष, उपाध्यक्ष, सचिव, सहसचिव और कोषाध्यक्ष का चुनाव गुप्त मतदान से होता है। महिला प्रकोष्ठ, युवा प्रकोष्ठ और अन्य प्रकोष्ठों के प्रभारी नामांकित किए जाते हैं।\n\n## नियम 3 — कार्यकारिणी समिति\nकार्यकारिणी में निर्वाचित पदाधिकारी, सभी क्षेत्रीय सचिव, प्रकोष्ठ प्रभारी, संरक्षक सदस्य (आजीवन) और पूर्व अध्यक्षगण (आजीवन) शामिल होते हैं।\n\nवर्तमान पदाधिकारियों की सूची [हमारे बारे में](/about) पेज पर देखें।", "width": "narrow"}]'::jsonb, 'published', false, 4, '{}'::jsonb)
