insert into public.cms_pages(organization_id, slug, title, title_hi, blocks, status, show_in_menu, menu_order, seo)
values ((select id from core.organizations where slug = 'pragatishil-kalar-samaj'), 'vivad-nirakaran', 'विवादों के निराकरण की प्रक्रिया', 'विवादों के निराकरण की प्रक्रिया', '[{"id": "t1", "type": "text", "heading": "अनुसूची 4 — विवादों के निराकरण की प्रक्रिया", "heading_hi": "अनुसूची 4 — विवादों के निराकरण की प्रक्रिया", "body": "1. **आवेदन** — व्यथित पक्ष लिखित आवेदन सचिव को देता है; आवेदन शुल्क ₹50। सामाजिक व्यवस्था के उल्लंघन की तीसरे पक्ष की शिकायत पर शुल्क नहीं।\n2. **बैठक में प्रकरण** — कार्यकारिणी की बैठक में कोई उल्लंघन सामने आए तो उसे तुरंत शिकायत के रूप में दर्ज किया जा सकता है।\n3. **पंजीयन व नोटिस** — सचिव आवेदन दर्ज कर अध्यक्ष के सामने रखता है; अध्यक्ष पक्षकारों को नोटिस और उपस्थिति का आदेश दे सकता है। आवेदन की पावती दी जाती है।\n4. **कारण बताओ नोटिस** — लिखित, जिसमें बैठक की तिथि, स्थान, समय हो; बिना कारण अनुपस्थिति पर एकपक्षीय कार्यवाही संभव।\n5. **सुनवाई** — प्रकरण पंजीयन-क्रम से सुने जाते हैं; पक्षकार दस्तावेज़ और मौखिक साक्ष्य दे सकते हैं, जो लिपिबद्ध होते हैं।\n6. **निर्णय** — सभी पक्षों को अवसर देने के बाद कार्यकारिणी बहुमत से निर्णय करती है और उसकी सार्वजनिक घोषणा होती है। हर विवाद की अलग नस्ती और आदेश-पत्रक रखा जाता है।\n7. **आपात बैठक** — गंभीर प्रकरण में, पक्षकार द्वारा ₹5100 जमा करने पर, सचिव अध्यक्ष की अनुमति से पूर्व-निर्धारित समय से पहले बैठक बुला सकता है।\n8. **पुनरीक्षण (अपील)** — निर्णय से असंतुष्ट पक्ष निर्णय की तिथि से **2 माह** के भीतर, ₹551 शुल्क के साथ, सचिव के माध्यम से **स्थायी समिति** को आवेदन दे सकता है; कार्यकारिणी द्वारा लगाया गया अर्थदंड चुकाने के बाद ही आवेदन स्वीकार होगा।\n9. **स्थायी समिति** — दोनों पक्षों को सुनकर कार्यकारिणी को अंतिम निर्णय हेतु अनुशंसा करती है, जो सर्वमान्य होगी।\n10. **अनुशासन** — महासभा/समिति की कार्यवाही में अनुशासनहीनता पर अध्यक्ष को उचित कार्यवाही का पूर्ण अधिकार है।", "body_hi": "1. **आवेदन** — व्यथित पक्ष लिखित आवेदन सचिव को देता है; आवेदन शुल्क ₹50। सामाजिक व्यवस्था के उल्लंघन की तीसरे पक्ष की शिकायत पर शुल्क नहीं।\n2. **बैठक में प्रकरण** — कार्यकारिणी की बैठक में कोई उल्लंघन सामने आए तो उसे तुरंत शिकायत के रूप में दर्ज किया जा सकता है।\n3. **पंजीयन व नोटिस** — सचिव आवेदन दर्ज कर अध्यक्ष के सामने रखता है; अध्यक्ष पक्षकारों को नोटिस और उपस्थिति का आदेश दे सकता है। आवेदन की पावती दी जाती है।\n4. **कारण बताओ नोटिस** — लिखित, जिसमें बैठक की तिथि, स्थान, समय हो; बिना कारण अनुपस्थिति पर एकपक्षीय कार्यवाही संभव।\n5. **सुनवाई** — प्रकरण पंजीयन-क्रम से सुने जाते हैं; पक्षकार दस्तावेज़ और मौखिक साक्ष्य दे सकते हैं, जो लिपिबद्ध होते हैं।\n6. **निर्णय** — सभी पक्षों को अवसर देने के बाद कार्यकारिणी बहुमत से निर्णय करती है और उसकी सार्वजनिक घोषणा होती है। हर विवाद की अलग नस्ती और आदेश-पत्रक रखा जाता है।\n7. **आपात बैठक** — गंभीर प्रकरण में, पक्षकार द्वारा ₹5100 जमा करने पर, सचिव अध्यक्ष की अनुमति से पूर्व-निर्धारित समय से पहले बैठक बुला सकता है।\n8. **पुनरीक्षण (अपील)** — निर्णय से असंतुष्ट पक्ष निर्णय की तिथि से **2 माह** के भीतर, ₹551 शुल्क के साथ, सचिव के माध्यम से **स्थायी समिति** को आवेदन दे सकता है; कार्यकारिणी द्वारा लगाया गया अर्थदंड चुकाने के बाद ही आवेदन स्वीकार होगा।\n9. **स्थायी समिति** — दोनों पक्षों को सुनकर कार्यकारिणी को अंतिम निर्णय हेतु अनुशंसा करती है, जो सर्वमान्य होगी।\n10. **अनुशासन** — महासभा/समिति की कार्यवाही में अनुशासनहीनता पर अध्यक्ष को उचित कार्यवाही का पूर्ण अधिकार है।", "width": "narrow"}]'::jsonb, 'published', false, 5, '{}'::jsonb)
