insert into public.cms_pages(organization_id, slug, title, title_hi, blocks, status, show_in_menu, menu_order, seo)
values ((select id from core.organizations where slug = 'pragatishil-kalar-samaj'), 'samajik-sanskar', 'जातीय एवं सामाजिक संस्कार', 'जातीय एवं सामाजिक संस्कार', '[{"id": "t1", "type": "text", "heading": "अनुसूची 5 — जातीय एवं सामाजिक संस्कार", "heading_hi": "अनुसूची 5 — जातीय एवं सामाजिक संस्कार", "body": "## (अ) जन्म\n- जन्म-सूतक की शुद्धि शास्त्रीय पद्धति से; जन्मोत्सव अपनी हैसियत के अनुसार, शुद्धि के बाद कभी भी।\n- आटे की लड्डू (ढूंढी, काके-पानी, सधौरी) की अनिवार्यता समाप्त; जन्मोत्सव में कपड़े का लेन-देन पूर्णतः प्रतिबंधित।\n- जन्म की सूचना क्षेत्रीय प्रतिनिधि के माध्यम से संगठन को दी जाए और पंजी में दर्ज हो।\n\n## (ब) विवाह\n- बाल विवाह की अनुमति नहीं; अवयस्क वर-कन्या का वाकदान नहीं होगा। विवाह की प्रक्रिया **वाकदान** और **फलदान** से पूरी होती है; वाकदान की सूचना क्षेत्रीय सचिव के माध्यम से संगठन को।\n- फलदान विवाह-तिथि से अधिकतम **एक माह** पहले; वर पक्ष **पाँच नारियल** व फलों का प्रसाद लाएगा; आभूषण की बाध्यता नहीं, कन्या के आवश्यक वस्त्र अनिवार्य। फलदान के बाद विवाह-अनुबंध पूर्ण; उल्लंघन करने वाला पक्ष समाज को क्षतिपूर्ति देगा (राशि कार्यकारिणी तय करेगी)।\n- बारात द्वार-पूजा के लिए **शाम 6 बजे** से पहले पहुँचे, विवाह यथासंभव उसी रात। जनवासा और बारातियों की संख्या कन्या पक्ष के परामर्श से तय हो; विदाई तक भोजन कन्या पक्ष की ओर से, शुद्ध शाकाहारी; **मद्यपान और मांसाहार पूर्णतः प्रतिबंधित**; भोजन चम्मच से परोसा जाए; एक पंगत अनिवार्य नहीं।\n- विवाह के समय रंग डालना मना; मांगलिक गीत हों पर अपशब्द नहीं; किसी को कष्ट देने वाला मनोरंजन नहीं, सुवासा (ढेंढा) को तंग न किया जाए।\n- नेग (न्यौछावर) का खर्च वर पक्ष; धोबी, नाई, पौनी, पसारी का खर्च कन्या पक्ष।\n- पिंवरी-धोवाई, तिजाहि और पूछनी प्रथाएँ समाप्त। द्विरागमन कन्यादान-पाणिग्रहण के तुरंत बाद; द्विरागमन में केवल दामाद को कपड़ा।\n- **दहेज की माँग पूर्णतः निषिद्ध।** मंडप में भेंट की सूची बने; उस पर पूर्ण स्वामित्व कन्या का।\n- विधवा विवाह को सामाजिक मान्यता और प्रोत्साहन; **बहुविवाह निषिद्ध**; तलाक केवल दोनों पक्षों की सहमति और कार्यकारिणी की संतुष्टि पर।\n- सामूहिक आदर्श विवाह को प्रोत्साहन — हर पक्ष कम से कम ₹501 जमा करेगा। निकट रक्त-संबंध, सगोत्र और बेमेल विवाह निषिद्ध।\n- विवाह का पंजीयन अनिवार्य — दोनों पक्ष ₹101 पंजीयन शुल्क देंगे।\n\n## (स) मृत्यु संस्कार\n- परिवार की शुद्धि शास्त्रीय विधान से; मृत्यु-भोज शुद्धि के बाद केवल **एक बार**; पिंडदान आदि में अनावश्यक खर्च न हो।\n- मृत्यु की सूचना संगठन को दी जाए और पंजी में दर्ज हो (इस वेबसाइट से शोक संदेश भेजे जा सकते हैं)।\n- पगड़ी रस्म अनिवार्य — नेंग पक्ष केवल **एक** पगड़ी बाँधेगा, शेष स्वेच्छा से आर्थिक सहायता; रणसारी में मायके से केवल **एक** साड़ी।\n- गंगा-अस्थि प्रवाह से लौटे लोगों को पगड़ी रस्म के समय आँगन में सामूहिक भेंट देना वर्जित।\n- दशगात्र के दिन सामूहिक स्नान के बाद चन्दन-पान और पगड़ी रस्म दोपहर में, उसके तुरंत बाद दिन में सामूहिक भोजन।", "body_hi": "## (अ) जन्म\n- जन्म-सूतक की शुद्धि शास्त्रीय पद्धति से; जन्मोत्सव अपनी हैसियत के अनुसार, शुद्धि के बाद कभी भी।\n- आटे की लड्डू (ढूंढी, काके-पानी, सधौरी) की अनिवार्यता समाप्त; जन्मोत्सव में कपड़े का लेन-देन पूर्णतः प्रतिबंधित।\n- जन्म की सूचना क्षेत्रीय प्रतिनिधि के माध्यम से संगठन को दी जाए और पंजी में दर्ज हो।\n\n## (ब) विवाह\n- बाल विवाह की अनुमति नहीं; अवयस्क वर-कन्या का वाकदान नहीं होगा। विवाह की प्रक्रिया **वाकदान** और **फलदान** से पूरी होती है; वाकदान की सूचना क्षेत्रीय सचिव के माध्यम से संगठन को।\n- फलदान विवाह-तिथि से अधिकतम **एक माह** पहले; वर पक्ष **पाँच नारियल** व फलों का प्रसाद लाएगा; आभूषण की बाध्यता नहीं, कन्या के आवश्यक वस्त्र अनिवार्य। फलदान के बाद विवाह-अनुबंध पूर्ण; उल्लंघन करने वाला पक्ष समाज को क्षतिपूर्ति देगा (राशि कार्यकारिणी तय करेगी)।\n- बारात द्वार-पूजा के लिए **शाम 6 बजे** से पहले पहुँचे, विवाह यथासंभव उसी रात। जनवासा और बारातियों की संख्या कन्या पक्ष के परामर्श से तय हो; विदाई तक भोजन कन्या पक्ष की ओर से, शुद्ध शाकाहारी; **मद्यपान और मांसाहार पूर्णतः प्रतिबंधित**; भोजन चम्मच से परोसा जाए; एक पंगत अनिवार्य नहीं।\n- विवाह के समय रंग डालना मना; मांगलिक गीत हों पर अपशब्द नहीं; किसी को कष्ट देने वाला मनोरंजन नहीं, सुवासा (ढेंढा) को तंग न किया जाए।\n- नेग (न्यौछावर) का खर्च वर पक्ष; धोबी, नाई, पौनी, पसारी का खर्च कन्या पक्ष।\n- पिंवरी-धोवाई, तिजाहि औ