insert into public.cms_pages(organization_id, slug, title, title_hi, blocks, status, show_in_menu, menu_order, seo)
values ((select id from core.organizations where slug = 'pragatishil-kalar-samaj'), 'lekha-pardarshita', 'लेखा व पारदर्शिता', 'लेखा व पारदर्शिता', '[{"id": "t1", "type": "text", "heading": "लेखा व पारदर्शिता", "heading_hi": "लेखा व पारदर्शिता", "body": "समाज अपने आय-व्यय का विवरण सार्वजनिक रखता है। पुरानी वेबसाइट (kalarsamaj.org) पर उपलब्ध दस्तावेज़:\n\n- [भूमि-भवन हेतु प्राप्त दान राशि (दानदाता सूची, PDF)](https://kalarsamaj.org/Images/Dandata.pdf)\n- [ऑडिट रिपोर्ट 2022-23 (PDF)](https://kalarsamaj.org/Images/Audit_Report.pdf)\n- [सदस्यता शुल्क व विवाह पंजीयन से प्राप्त राशि](https://kalarsamaj.org/UC.aspx)\n\nनई प्राप्तियाँ और खर्च अब इसी मंच के लेखा module में दर्ज होंगे।", "body_hi": "समाज अपने आय-व्यय का विवरण सार्वजनिक रखता है। पुरानी वेबसाइट (kalarsamaj.org) पर उपलब्ध दस्तावेज़:\n\n- [भूमि-भवन हेतु प्राप्त दान राशि (दानदाता सूची, PDF)](https://kalarsamaj.org/Images/Dandata.pdf)\n- [ऑडिट रिपोर्ट 2022-23 (PDF)](https://kalarsamaj.org/Images/Audit_Report.pdf)\n- [सदस्यता शुल्क व विवाह पंजीयन से प्राप्त राशि](https://kalarsamaj.org/UC.aspx)\n\nनई प्राप्तियाँ और खर्च अब इसी मंच के लेखा module में दर्ज होंगे।", "width": "narrow"}]'::jsonb, 'published', false, 7, '{}'::jsonb)
