insert into public.cms_menus(organization_id, location, items) values ((select id from core.organizations where slug = 'pragatishil-kalar-samaj'), 'footer', '[{"label": "संविधान", "label_hi": "संविधान", "to": "/p/samvidhan"}, {"label": "सदस्यता नियम", "label_hi": "सदस्यता नियम", "to": "/p/sadasyata-niyam"}, {"label": "क्षेत्र व आश्रित ग्राम", "label_hi": "क्षेत्र व आश्रित ग्राम", "to": "/p/kshetra-vibhajan"}, {"label": "सामाजिक संस्कार", "label_hi": "सामाजिक संस्कार", "to": "/p/samajik-sanskar"}, {"label": "लेखा व पारदर्शिता", "label_hi": "लेखा व पारदर्शिता", "to": "/p/lekha-pardarshita"}]'::jsonb)
on conflict (organization_id, location) do update set items = excluded.items;